		attribute.
			Key("sql.query").
			String("SELECT id, name, coordinates FROM locations"),
	)
	defer span.End()

	query := "SELECT id, name, coordinates FROM locations"
	rows, err := d.db.Query(query)
	if err != nil {
		if !d.shouldRetry(err) {
			return nil, err
		}
		rows, err = d.db.Query(query)
		if err != nil {
			return nil, err
		}
	}
	defer rows.Close()
	var cs []Location
	for rows.Next() {
