async (page) => {
  const key = 'xsl87gsqrc2gl';
  await page.context().route('**/*', async (route) => {
    const h = { ...route.request().headers() };
    h['baggage'] = (h['baggage'] ? h['baggage'] + ',' : '') + 'sd-routing-key=' + key;
    h['tracestate'] = 'sd-routing-key=' + key;
    await route.continue({ headers: h });
  });
  const errors = [];
  page.on('pageerror', e => errors.push(String(e)));
  page.on('console', m => { if (m.type() === 'error') errors.push(m.text()); });
  await page.goto('http://frontend.ctbench-hotrod.svc:8080/', { waitUntil: 'networkidle' });
  const opts = await page.locator('select').first().locator('option').allTextContents();
  const vals = await page.locator('select').first().locator('option').evaluateAll(o => o.map(x => x.value));
  await page.locator('select').nth(0).selectOption('1');
  await page.locator('select').nth(1).selectOption('123');
  await page.getByRole('button', { name: 'Request Ride' }).click();
  await page.getByRole('button', { name: 'Show Logs' }).click();
  await page.waitForTimeout(8000);
  const text = await page.locator('body').innerText();
  await page.screenshot({ path: '/tmp/ui.png' });
  return { opts, vals, errors, text: text.slice(0, 1500) };
}

