  await p.locator('select').nth(0).selectOption('1');
  await p.locator('select').nth(1).selectOption('123');
  await p.getByRole('button', { name: 'Request Ride' }).click();
  await p.waitForTimeout(5000);
  const js = await p.evaluate(() => [...document.scripts].map(s => s.src));
  await ctx.close();
  return { errors, js };
})(page);
